arguments.new_str:
using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "MyMcpServer", Version = "1.0.0" };
    })
    .WithHttpTransport()
    .WithTools<MyTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

/// <summary>Tools exposed by the MCP server.</summary>
public class MyTools
{
    [McpServerTool, Description("Adds two numbers together.")]
    public static int Add(int a, int b) => a + b;

    [McpServerTool, Description("Returns the current UTC time.")]
    public static string GetTime() => DateTime.UtcNow.ToString("o");
}

/// <summary>Resources exposed by the MCP server.</summary>
public class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings",
        MimeType = "application/json")]
    [Description("Returns application configuration data.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };
        return System.Text.Json.JsonSerializer.Serialize(config);
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "AppVersion",
        MimeType = "text/plain")]
    [Description("Returns the application version.")]
    public static string GetAppVersion() => "1.0.0";
}

